import { useNavigate } from '@tanstack/react-router';
const photos = [{ id: '1', thumb: '/img/1-thumb.jpg' }, { id: '2', thumb: '/img/2-thumb.jpg' }];
export function Gallery() {
  const navigate = useNavigate();
  return (
    <ul className="gallery">
      {photos.map(p => (
        <li key={p.id}><img src={p.thumb} alt="" onClick={() => navigate({ to: '/photo/$id', params: { id: p.id } })} /></li>
      ))}
    </ul>
  );
}

