import { useQuery } from '@tanstack/react-query';
type Asset = { id: string; name: string };
export function AssetList() {
  const { data, isPending, isError } = useQuery({ queryKey: ['assets'], queryFn: () => fetch('/api/assets').then(r => { if (!r.ok) throw new Error('failed'); return r.json() as Promise<Asset[]>; }) });
  if (isPending) return <p>Loading assets…</p>;
  if (isError) return <p role="alert">Could not load assets</p>;
  return <ul>{data.map(a => <li key={a.id}>{a.name}</li>)}</ul>;
}

